const int P = 998244353;
struct Tag {
    long long mul = 1, add = 0;
    void apply(Tag t) {
        mul = mul * t.mul % P;
        add = (add * t.mul + t.add) % P;
    }
};
struct Info {
    long long sum = 0;
    int len = 0;
    void apply(Tag t) {
        sum = (sum * t.mul + t.add * len) % P;
    }
    Info operator+(Info b) const {
        return {(sum + b.sum) % P, len + b.len};
    }
};
int main() {
    vector<Info> a = {{0, 0}, {1, 1}, {2, 1}, {3, 1}};
    LazySeg<Info, Tag> s(a);
    s.apply(1, 3, {2, 1}); // x -> 2x+1，得到 3,5,7。
    s.apply(2, 3, {0, 4}); // 赋值为4；加c用 {1,c}。
    assert(s.query(1, 3).sum == 11);
}

struct Info {
    int sum = 0;
    void apply(Info b) {
        sum += b.sum;
    }
    Info operator+(Info b) const {
        return {sum + b.sum};
    }
    Info operator-(Info b) const {
        return {sum - b.sum};
    }
};
int main() {
    vector<int> a = {0, 5, 1, 5, 3}, v(a.begin() + 1, a.end());
    sort(v.begin(), v.end());
    v.erase(unique(v.begin(), v.end()), v.end());
    int n = a.size() - 1, m = v.size();
    PST<Info> s(m, n);
    vector<int> rt(n + 1);
    for(int i = 1; i <= n; i++) {
        int x = lower_bound(v.begin(), v.end(), a[i]) - v.begin() + 1;
        rt[i] = s.modify(rt[i - 1], x, {1});
    }
    int l = 2, r = 4, k = 2; // 闭区间；k需合法。
    int x = s.first(rt[l - 1], rt[r], 1, m, [&](Info t) { return t.sum >= k; });
    assert(v[x - 1] == 3);
}

