int main() {
    vector<vector<int>> g(5);
    for(int u = 2; u <= 4; u++) {
        g[1].push_back(u), g[u].push_back(1);
    }
    vector<int> color = {0, 1, 1, 2, 2}, cnt(3), ans(5);
    int cur = 0;
    DSUOnTree s(g);
    s.run(
        [&](int u, int d) {
            if(cnt[color[u]]) {
                cur--;
            }
            cnt[color[u]] += d;
            if(cnt[color[u]]) {
                cur++;
            }
        },
        [&](int u) { ans[u] = cur; });
    assert(ans[1] == 2 && ans[2] == 1 && cur == 0);
}

int main() {
    vector<vector<int>> g(6);
    for(int u = 2; u <= 5; u++) {
        g[u - 1].push_back(u), g[u].push_back(u - 1);
    }
    LCA l(g);
    Centroid c(g);
    const int INF = 1000000000;
    vector<int> best(6, INF);
    auto add = [&](int u) {
        for(int x = u; x; x = c.parent[x]) {
            best[x] = min(best[x], l.dis(u, x));
        }
    };
    auto query = [&](int u) {
        int ans = INF;
        for(int x = u; x; x = c.parent[x]) {
            ans = min(ans, best[x] + l.dis(u, x));
        }
        return ans;
    };
    add(1);
    add(5);
    assert(query(3) == 2 && query(4) == 1);
}

