    vector<vector<int>> a = {{0, 0, 0, 0}, {0, 1, 2, 5}, {0, 2, 100, 0}, {0, 3, 1, 5}};
    vector<int> w;
    int r = gaussMod(a, P, w);
    bool ok = true;
